import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.Ky-Ipuyb.js";const u=JSON.parse('{"title":"RmlUi rendering and Retina","description":"","frontmatter":{"lang":"en","sourcePath":"docs/rmlui/rendering.md"},"headers":[],"relativePath":"rmlui/rendering.md","filePath":"rmlui/rendering.md"}'),n={name:"rmlui/rendering.md"};function o(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rmlui-rendering-and-retina" tabindex="-1">RmlUi rendering and Retina <a class="header-anchor" href="#rmlui-rendering-and-retina" aria-label="Permalink to &quot;RmlUi rendering and Retina&quot;">​</a></h1><p>RmlUi layout and geometry stay in the native backend. SFML handles vertex buffers, textures, shaders and render targets. Use the same open <code>RenderWindow</code> for the runtime&#39;s whole lifetime.</p><p>Renderer creation requires SFML shader support and all six required programs. Missing support or compilation failure throws before registration or selection. Failed geometry or clip-mask uploads abort the UI frame and restore the host view. If only a merged batch allocation fails, individual draws preserve the submitted sequence.</p><h2 id="compose-a-frame" tabindex="-1">Compose a frame <a class="header-anchor" href="#compose-a-frame" aria-label="Permalink to &quot;Compose a frame&quot;">​</a></h2><p>Clear the window, record your SFML scene, call <code>window.flush()</code>, render the RmlUi context, then call <code>window.display()</code>. Flushing submits recorded scene commands before RmlUi draws. Call <code>context.update()</code> before rendering to apply layout, animations and display density.</p><p>Each <code>context.render()</code> owns a transparent UI base layer and presents it over the host scene only after successful traversal. It restores the host <code>View</code> and adapter state on success or failure. Callback failures discard the current UI frame. Render callbacks see the already submitted host scene; UI pixels become visible in the window when the frame completes.</p><p>Context frames and pushed layers own verified eight-bit stencil buffers. Request <code>settings.stencilBits: 8</code> for direct <code>RenderManager</code> draws into the window outside a context frame.</p><p>Layer zero can be a source or destination, including self-composites and saved alpha masks. Inside a context frame it contains only RmlUi content. Direct manager operations outside a context frame read the host window as layer zero. Spare layers retain at most eight size-compatible targets within a 32 MiB storage budget; resizing releases old-size targets.</p><h2 id="physical-pixels-and-dp" tabindex="-1">Physical pixels and <code>dp</code> <a class="header-anchor" href="#physical-pixels-and-dp" aria-label="Permalink to &quot;Physical pixels and `dp`&quot;">​</a></h2><p>On macOS, <code>initialise(window)</code> enables the native Retina surface while preserving the window&#39;s on-screen size. Afterwards, window sizes, mouse/resize events and texture captures use physical pixels. Create the RmlUi context from <code>window.getSize()</code> <strong>after</strong> initialization.</p><table tabindex="0"><thead><tr><th>At density 2</th><th>Result</th></tr></thead><tbody><tr><td>1024 × 768 on-screen window</td><td>2048 × 1536 framebuffer and context</td></tr><tr><td><code>font-size: 20dp</code></td><td>40 physical pixels, preserving apparent size</td></tr><tr><td><code>font-size: 20px</code></td><td>20 physical pixels</td></tr><tr><td>Mouse input</td><td>Forward directly without another scale multiplication</td></tr></tbody></table><p>The context refreshes <code>densityIndependentPixelRatio</code> on update. <code>processEvent</code> handles resize dimensions. <code>context.dimensions</code> is a cached readonly view; use <code>setDimensions(width, height)</code> to update native layout.</p><p><code>initialise(window, { highDpi: false })</code> preserves the current surface, including one already enabled. Once enabled, the surface stays enabled until the window closes, even after <code>shutdown()</code>. Other platforms use the density reported by the backend, currently 1.</p><h2 id="renderer-coverage" tabindex="-1">Renderer coverage <a class="header-anchor" href="#renderer-coverage" aria-label="Permalink to &quot;Renderer coverage&quot;">​</a></h2><p>See <a href="/rmlui/render-state">render state</a> for viewport, scissor, owned geometry masks, matrix submission and save/restore operations.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Current support</th></tr></thead><tbody><tr><td>Text, textures, solid geometry, scissor</td><td>Implemented</td></tr><tr><td>Stencil clip masks and rounded overflow</td><td>Implemented; needs a stencil buffer</td></tr><tr><td>Offscreen layers and compositing</td><td>Implemented through SFML render textures</td></tr><tr><td>Blur and drop shadow</td><td>Implemented through SFML shaders</td></tr><tr><td>Saved layer alpha masks</td><td>Implemented; positioned scissor snapshots</td></tr><tr><td>Linear, radial, conic and repeating gradients; creation</td><td>Native programs with complete stop lists and homogeneous transforms</td></tr><tr><td>CSS image masks</td><td>Implemented; foreground/backdrop/mask combinations compared against GL3 on macOS</td></tr><tr><td>Opacity, brightness, contrast, invert, grayscale, sepia, hue rotation, saturation</td><td>Implemented through native premultiplied color shaders</td></tr><tr><td>Backdrop filters</td><td>Readable UI base layer and combined CSS effects verified on macOS</td></tr><tr><td>4×4 geometry and clip transforms</td><td>Native homogeneous projection, Z clipping and perspective texture interpolation</td></tr></tbody></table><p>The <a href="/examples/rmlui#visual-tests">VisualTests launcher</a> previews upstream pages. A page loading without a crash does not certify its visual assertions or full RmlUi renderer coverage.</p><p>Color filters preserve list order. <code>RenderManager.compileFilter(name, { value })</code> uses the native names <code>opacity</code>, <code>brightness</code>, <code>contrast</code>, <code>invert</code>, <code>grayscale</code>, <code>sepia</code>, <code>hue-rotate</code> and <code>saturate</code>; hue angles are radians. Omitted values default to 1. Explicit values must be finite numbers. Color matrices preserve premultiplied alpha and transparent pixels. Invert and opacity clamp to 0–1. Like the pinned GL3 renderer, matrix output clamps to the RGBA8 channel range, not source alpha. Ordinary loaded, generated, preloaded and saved-layer textures use linear filtering and repeat addressing, including UVs outside 0–1. Unavailable effect shaders produce an invalid compilation handle.</p><p><code>blur</code> uses <code>{ sigma }</code> (default 1), with finite, nonnegative sigma in physical pixels. Large radii use the pinned GL3 iterative half-scaling and seven-point Gaussian kernel, then stable power-of-two placement. Samples outside the active scissor window contribute transparent pixels. A reduced window with no remaining samples produces transparent output.</p><p><code>drop-shadow</code> uses <code>{ sigma, offset, color }</code>: sigma defaults to 0, offset to <code>{ x: 0, y: 0 }</code>, and color to opaque black. Offsets must be finite physical pixels; positive Y points down. Color contains straight RGBA bytes. The shader shifts and tints source alpha before optional blur (sigma ≥ 0.5), then places the unchanged source over the shadow. Ordered filter chains use three reusable SFML scratch targets, retaining premultiplied pixels and the source layer. The macOS native suite compares 16 odd-size, full/scissored captures against the pinned official GL3 backend and also checks transparency, source retention, fractional/negative offsets and scratch reuse.</p><p>Ten real RML/CSS scenes cover foreground filters, backdrop filters, gradient masks, every combination and transformed rounded overflow. The macOS GL3/SFML checks require a maximum RGB channel difference of at most 2 and a mean difference of at most 0.1. Repeated frames and reverse scene order preserve exact SFML pixels, including premultiplied alpha and transparent corners. Twelve native allocation groups cover base/layer/scratch/capture failures and retries. A failed mask-record allocation releases its already captured texture. Full application and VisualTests acceptance remains separate.</p><p>Geometry and clip masks share a full column-major transform. Geometry translation precedes that transform; the projection uses top-left physical pixels and a Z range of −10000 to 10000. Clip definitions retain their write-scissor and transform snapshots. Intersections remain boolean for overlapping triangles and normalize stencil values before eight-bit exhaustion. The custom <code>vertex_shader</code> extension retains its supplied vertex program and legacy SFML affine transform convention.</p><h2 id="gradient-and-creation-dictionaries" tabindex="-1">Gradient and creation dictionaries <a class="header-anchor" href="#gradient-and-creation-dictionaries" aria-label="Permalink to &quot;Gradient and creation dictionaries&quot;">​</a></h2><p><code>RenderManager.compileShader</code> accepts <code>linear-gradient</code> with <code>p0</code> and <code>p1</code>, <code>radial-gradient</code> with <code>center</code> and positive <code>radius</code>, and <code>conic-gradient</code> with <code>center</code> and <code>angle</code> in radians. These use local pixel UVs, optional <code>repeating</code> (default false), and a tagged <code>color_stop_list</code>. Stop positions must be finite, nondecreasing numbers with <code>Unit.NUMBER</code>; colors already contain premultiplied bytes. All stops participate in successive GL3 <code>smoothstep</code> mixing, including lists longer than 16. The complete stop list is specialized into GLSL; if the GPU cannot compile it, the resource is invalid.</p><p>A single stop paints a constant color. Equal positions switch to the later color at that position. Repeats wrap between the first and last position; a zero repeat interval paints the final color. Empty or descending stops, coincident linear endpoints, nonpositive radial radii and nonfinite parameters return invalid resources. At a conic center the gradient coordinate is zero.</p><p>Use name <code>shader</code> with <code>{ value: &#39;creation&#39;, dimensions: { x, y } }</code> for creation. Dimensions must be finite and positive. It uses normalized local UVs and elapsed seconds from <code>SystemInterface</code>, preserving the pinned GL3 RGB equation and vertex alpha. Its center and reciprocal denominators have a <code>1e-6</code> lower bound to produce finite pixels. Built-ins use the full 4×4 transform and ignore the optional texture. Explicit <code>vertex_shader</code> and <code>fragment_shader</code> parameters select the custom GLSL extension, with its SFML affine coordinate convention.</p><h2 id="verify-density" tabindex="-1">Verify density <a class="header-anchor" href="#verify-density" aria-label="Permalink to &quot;Verify density&quot;">​</a></h2><p>From <code>packages/sfml.js-rmlui</code>, run <code>npm test</code>; on macOS also run <code>npm --prefix ../sfml.js-interop run test:high-dpi</code>. Regression checks cover 1×/Retina layout, glyph rasterization, hit testing, resize, physical pixel capture and limits. Moving the window between physical monitors still needs device testing.</p>',28)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
